import sys, json, re, os, secrets, datetime, hashlib, base64, subprocess

# GIT AS THE EXCHANGE FORMAT OF A PROJECTION (GH #906, K7/R-27-5). git is how a
# workspace leaves the hive and how a repository comes in -- never where a
# file lives: nothing here ever reads the hive out of `.git`, and every byte
# that enters goes through `./write` of the file space like any other write.
#
# The repository of a workspace is `<git_dir>/<ws>`, a bare repository whose
# work tree is the projection's directory `<base_path>/<ws>` (every call names
# both: `--git-dir`, `--work-tree`). It never lies under `base_path` (GH #980
# M1): `run` may write all of `base_path`, and the program of a model's
# `file_ws_exec` wrote `filter.<x>.clean` or `url.<r>.insteadOf` into an
# in-tree `.git/config` -- code in this cell on the next export, the next push
# to a repository nobody configured. The owner grants `git_dir` to this cell
# alone; a `git_dir` missing, relative or inside `base_path` is `no_git_dir`.
# The same holds for the target of a push: a remote that is a local path
# under `base_path` (lexical or after symlinks) is `remote_inside_base`
# before git runs. `run` could write that repository's `hooks/`, and a local
# push runs the receiving side's hooks in this cell's process.
# A `.git` a program leaves in the work tree is a file like any other and is
# never read as a repository. `git` runs as a subprocess with an argv list --
# never a shell -- under an explicit environment (no host or user
# configuration is read, HOME is the repository, `core.autocrlf=false`,
# literal pathspecs) and with a time cap per call.
#
#   ws_export_git  materialize (`./mat`), stage ONLY the manifest's paths (a
#                  tool's `target/` or caches in the same directory never land
#                  in a commit), one commit whose parents are the old head and,
#                  when it is no ancestor yet, `refs/meclaw/upstream`
#   ws_import_git  fetch into the projection's own repository (held by
#                  `refs/meclaw/incoming`), compare its tree with `ws_tree`,
#                  write the difference into the workspace one file at a time
#                  (`create`, `overwrite` against the working version,
#                  `remove`), and only after the last write went through
#                  remember the commit as `refs/meclaw/upstream`; the
#                  workspace is touched, not committed
#   ws_push        the exported head, by its sha, to `refs/heads/<branch>`; a
#                  refused push is `push_rejected`, never a force push
#                  (OR-FJ-GIT1)
#   ws_pull        `ws_import_git` from a remote's branch
#
# THE ROOT FORM (GH #980): `ws_export_git` and `ws_push` with `args.root` and
# no `hop.ws` address the git projection OF A ROOT -- the directory
# `<base_path>/<view_of(root)>`, the same for every call on that root. An
# export opens a workspace of that name over the root, exports it and
# discards it again (the caller opens nothing; a pull into a workspace of
# the same name fills the same repository), and a push of the root form
# takes `remote` only as a name of `remotes` -- the form a model's tool
# sends, so no URL or path of a model is ever a remote.
#
# The cell runs `cold`: a request that waits for another cell (`./mat`, the
# file space) is a job parked in `pending` (`cell` = 'git'); every answer comes
# back on `in_answer` under `op_id` `git:<job>.<n>` and is parked next to the
# job before the job reads on -- never recognised by `context.cur_origin`,
# which the called cell overwrites on its own store edge (B1 README 2.2).
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}

ME = "git"
CALLER = "projection"
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"
OPS = ("ws_export_git", "ws_import_git", "ws_push", "ws_pull")
NAME_RE = re.compile(r"^[A-Za-z0-9._-]{1,64}$")
REF_RE = re.compile(r"^[A-Za-z0-9._/-]{1,200}$")
# Any userinfo of a URL -- `user:secret@` and a bare `token@` alike (a
# personal access token is often the user part alone).
CRED_RE = re.compile(r"([A-Za-z][A-Za-z0-9+.-]*://)[^/@\s]+@")
SCP_RE = re.compile(r"^[^/:@\s]+@[^/:\s]+:")
TAIL_BYTES = 4096
UPSTREAM = "refs/meclaw/upstream"
# The fetched commit until the pull is through: it keeps the objects
# reachable without making the commit an export parent (review I-1).
INCOMING = "refs/meclaw/incoming"
# A head an export moved HEAD away from without it being in the new HEAD's
# line (L-8 beside the upstream): kept under this prefix, never deleted.
SUPERSEDED = "refs/meclaw/superseded/"
DEFAULT_AUTHOR = "meclaw <meclaw@example.invalid>"
VIEW = "git"
ROW_LIMIT = 50
# A job whose answer never came (a called cell timed out without route or
# `op_id`, B1-PP-14) is cleared by the next request after an hour -- the
# same rule as `mat` (OR-FJ-64).
JOB_TTL_MS = 3600000
CRED_MSG = "a remote with a user or secret in its URL is not supported (no credential path)"
SKIP_MODES = {"120000": "symlink", "160000": "submodule"}
# The environment of every `git` call of this run, set once per message
# (`use_env`); a dict, so the pure half loads without a job.
GIT_ENV = {}


# ================================================================ PURE HALF
def mask(text):
    """Every userinfo `scheme://user[:secret]@` in `text` becomes
    `scheme://***@`: no git output and no remote in an answer carries
    credentials."""
    return CRED_RE.sub(lambda m: m.group(1) + "***@", str(text or ""))


def tail(text, limit=TAIL_BYTES):
    """The last `limit` bytes of `text` (UTF-8, cut on a character), masked."""
    raw = mask(text).encode("utf-8")
    if len(raw) <= limit:
        return raw.decode("utf-8")
    return raw[-limit:].decode("utf-8", "ignore")


def valid_ref(s):
    """A ref or branch name git would take and no option could hide in: no
    leading `-` or `/`, no `..`, `//`, `@{`, trailing `/`, `.lock` or `.`."""
    s = str(s or "")
    if not REF_RE.match(s) or s[0] in "-/" or s.endswith("/") or s.endswith("."):
        return False
    if ".." in s or "//" in s or s.endswith(".lock"):
        return False
    return all(part and not part.startswith(".") for part in s.split("/"))


def resolve_remote(arg, remotes):
    """The URL or path behind a remote argument: a name of `remotes` gives its
    value, anything else is taken only as an absolute local path without `..`
    segments; everything else is None (`remote_unknown`)."""
    arg = str(arg or "")
    if not arg:
        return None
    if isinstance(remotes, dict) and arg in remotes and isinstance(remotes[arg], str) \
            and remotes[arg]:
        return remotes[arg]
    if arg.startswith("/") and "\x00" not in arg and ".." not in arg.split("/"):
        return arg
    return None


def has_userinfo(url):
    """Whether a remote URL carries a user part (`scheme://user@host`, also
    with a secret, or the scp form `user@host:path`). B2 has no credential
    path (OR-FJ-71): such a remote is `credentials_unsupported`, never used.
    An `@` in the path of a URL or a local path is none."""
    url = str(url or "")
    if url.startswith("/"):
        return False
    m = re.match(r"^[A-Za-z][A-Za-z0-9+.-]*://([^/]*)", url)
    if m:
        return "@" in m.group(1)
    return bool(SCP_RE.match(url))


def local_path(url):
    """The local path a remote names -- an absolute path or a `file://` URL
    -- or None for a remote on another transport."""
    url = str(url or "")
    if url.startswith("file://"):
        url = url[len("file://"):]
        if not url.startswith("/"):
            return None
    if not url.startswith("/") or "\x00" in url:
        return None
    return url


def remote_inside_base(url, base):
    """Whether a local remote lies under `base`, is `base`, or holds it --
    lexical and after symlinks. `run` may write all of `base`, so a bare
    repository there can carry a hook a program planted, and `git push` to a
    local path runs the receiving side's `pre-receive`/`update`/`post-receive`
    hooks in this cell's process (Welle Loop NV2, the class of GH #980 M1).
    A remote on another transport is not local and never inside."""
    p, b = local_path(url), str(base or "")
    if p is None or not b.startswith("/"):
        return False
    for pp, bb in ((os.path.normpath(p), os.path.normpath(b)),
                   (os.path.realpath(p), os.path.realpath(b))):
        if pp == bb or pp.startswith(bb.rstrip("/") + "/") or bb.startswith(pp.rstrip("/") + "/"):
            return True
    return False


def repo_path(path, root):
    """The repository path of a hive path under the workspace root, or None:
    a path outside the root, the root itself, or with `.`/`..`/empty
    segments never becomes a path of a commit (OR-FJ-70, root-relative)."""
    path = str(path or "")
    if not path.startswith("/") or "\x00" in path:
        return None
    r = str(root or "/").rstrip("/")
    if r and not path.startswith(r + "/"):
        return None
    rel = path[len(r) + 1:]
    if not rel or any(p in ("", ".", "..") for p in rel.split("/")):
        return None
    return rel


def norm_root(root):
    """`root` as an absolute folder path without a trailing slash (`/` stays
    `/`), or None: a relative path, a NUL, an empty, `.` or `..` segment."""
    root = str(root or "")
    if not root.startswith("/") or "\x00" in root:
        return None
    segs = root.strip("/").split("/") if root.strip("/") else []
    if any(p in ("", ".", "..") for p in segs):
        return None
    return "/" + "/".join(segs)


def view_of(root):
    """The workspace name -- and so the directory under `base_path` -- of the
    git projection of `root` (GH #980): `git` for `/`, `git.<a>.<b>` for
    `/a/b`. A segment outside the name rule, a dot inside one (`/a.b` and
    `/a/b` must not share a directory) or a name past 64 characters gets a
    readable stem and the first 12 hex digits of the root's sha256."""
    segs = [p for p in str(root or "/").split("/") if p]
    name = ".".join([VIEW] + segs)
    if NAME_RE.match(name) and not any("." in p for p in segs):
        return name
    stem = re.sub(r"[^A-Za-z0-9_-]", "_", name)[:47]
    return stem + "." + hashlib.sha256(str(root).encode("utf-8")).hexdigest()[:12]


def git_root(base, git_dir):
    """`git_dir` normalized, or None: it must be absolute and lie outside
    `base` -- not `base` itself, not below it, and not above it either (a
    repository `<git_dir>/<ws>` above `base` could be `base` or a workspace
    directory under it). Lexical and after symlinks."""
    g, b = str(git_dir or ""), str(base or "")
    if not g.startswith("/") or not b.startswith("/") or "\x00" in g:
        return None
    for gg, bb in ((os.path.normpath(g), os.path.normpath(b)),
                   (os.path.realpath(g), os.path.realpath(b))):
        if gg == bb or gg.startswith(bb.rstrip("/") + "/") or bb.startswith(gg.rstrip("/") + "/"):
            return None
    return os.path.normpath(g)


def gitdir_of(repo):
    """The repository of the work tree `repo` (`<base_path>/<ws>`):
    `<git_dir>/<ws>`."""
    return os.path.join(str(P.get("git_dir") or ""), os.path.basename(os.path.normpath(str(repo))))


def hive_path(rel, root):
    """The hive path of a repository path in a workspace rooted at `root`
    (the inverse of `repo_path`)."""
    return str(root or "/").rstrip("/") + "/" + rel


def git_segment(rel):
    """Whether a path names `.git` at any depth (any case): nothing below it
    enters the hive or a commit -- a foreign `.git/config` or hook would run
    code in the projection on the next git call (OR-FJ-72)."""
    return any(p.lower() == ".git" for p in str(rel or "").split("/"))


def parse_author(s):
    """`Name <mail>` -> (name, mail); anything else is the default author."""
    m = re.match(r"^\s*([^<>]+?)\s*<([^<>\s]+)>\s*$", str(s or ""))
    if not m:
        m = re.match(r"^\s*([^<>]+?)\s*<([^<>\s]+)>\s*$", DEFAULT_AUTHOR)
    return m.group(1), m.group(2)


def git_env(home, author):
    """The whole environment of every `git` call: nothing of the host's
    environment and no system, global or user configuration."""
    name, mail = parse_author(author)
    env = {"PATH": "/usr/bin:/bin", "HOME": home, "LANG": "C", "LC_ALL": "C",
           "GIT_CONFIG_NOSYSTEM": "1", "GIT_CONFIG_GLOBAL": "/dev/null",
           "GIT_TERMINAL_PROMPT": "0", "GIT_LITERAL_PATHSPECS": "1",
           "GIT_AUTHOR_NAME": name, "GIT_AUTHOR_EMAIL": mail,
           "GIT_COMMITTER_NAME": name, "GIT_COMMITTER_EMAIL": mail}
    return env


def argv(repo, *args):
    """One `git` call on the work tree `repo` and its repository under
    `git_dir` (GH #980 M1), as an argv list. Both are named, so no `.git`
    in the work tree is ever discovered."""
    # `core.hooksPath=/dev/null` and `core.fsmonitor=false` outrank the
    # repository's own config: a hook or fsmonitor in `.git` never runs
    # (OR-FJ-72; the FR1 lock armed both and saw them run without this).
    return ["git", "--git-dir=" + gitdir_of(repo), "--work-tree=" + str(repo),
            "-c", "core.autocrlf=false", "-c", "core.symlinks=true",
            "-c", "core.hooksPath=/dev/null", "-c", "core.fsmonitor=false",
            "-c", "advice.detachedHead=false"] + [str(a) for a in args]


def argv_fetch(repo, source, ref):
    return argv(repo, "fetch", "--no-tags", "--quiet", "--", source, ref)


def argv_push(repo, url, branch, commit):
    # Never `--force` and never a `+` refspec (OR-FJ-GIT1). The commit by its
    # sha, read once before the push: what leaves is what the answer names.
    return argv(repo, "push", "--quiet", "--porcelain", "--", url,
                commit + ":refs/heads/" + branch)


def argv_commit_tree(repo, tree, parents, note):
    out = ["commit-tree", tree]
    for p in parents:
        out += ["-p", p]
    return argv(repo, *(out + ["-m", note]))


def parse_ls_tree(raw):
    """`git ls-tree -r -z -l` -> [{mode, type, sha, size, path}], `size` -1
    where git prints `-` (a submodule). A path that is not UTF-8 keeps its
    bytes escaped and is marked `bad_path`."""
    if isinstance(raw, str):
        raw = raw.encode("utf-8", "surrogateescape")
    out = []
    for rec in raw.split(b"\x00"):
        if not rec:
            continue
        meta, _, pb = rec.partition(b"\t")
        parts = meta.decode("ascii", "replace").split()
        if len(parts) < 4:
            continue
        mode, typ, sha, size = parts[0], parts[1], parts[2], parts[3]
        try:
            path, bad = pb.decode("utf-8"), False
        except UnicodeDecodeError:
            path, bad = pb.decode("utf-8", "backslashreplace"), True
        e = {"mode": mode, "type": typ, "sha": sha,
             "size": int(size) if size.isdigit() else -1, "path": path}
        if bad:
            e["bad"] = True
        out.append(e)
    return out


def skip_reason(e, max_bytes):
    """Why an entry of the tree does not enter the hive, or '' if it does."""
    if e.get("bad") or "\n" in e["path"] or "\r" in e["path"] or git_segment(e["path"]):
        return "bad_path"
    if e["path"].startswith("/") or any(p in ("", ".", "..") for p in e["path"].split("/")):
        return "outside_root"
    if e["mode"] in SKIP_MODES:
        return SKIP_MODES[e["mode"]]
    if e["type"] != "blob":
        return "not_a_file"
    if e["size"] > max_bytes:
        return "too_large"
    return ""


def import_plan(entries, tree, root, held):
    """What an import writes: `entries` are the source's files `{path, sha,
    digest}` (`digest` the sha256 of the bytes, `path` repository-relative),
    `tree` is `ws_tree`'s `files` `{file, path, version}` (`version` 12 hex),
    `root` the workspace root the repository maps onto (OR-FJ-70), `held` the
    hive paths the import skipped. Same bytes -> nothing; another content ->
    `overwrite` against the workspace version; a new path -> `create`; a path
    only in the workspace -> `remove` -- unless it lies outside the root or
    was skipped (a symlink in the source keeps the workspace's file). In path
    order."""
    have = {}
    for t in tree or []:
        p = str(t.get("path") or "")
        if p and repo_path(p, root) is not None:
            have[p] = t
    steps, same, seen = [], 0, set(held or [])
    for e in sorted(entries, key=lambda x: x["path"]):
        p = hive_path(e["path"], root)
        seen.add(p)
        t = have.get(p)
        if t is None:
            steps.append({"do": "create", "path": p, "sha": e["sha"]})
        elif e["digest"][:12] == str(t.get("version") or "")[:12]:
            same += 1
        else:
            steps.append({"do": "overwrite", "path": p, "sha": e["sha"],
                          "file": t["file"], "base": t["version"]})
    for p in sorted(have):
        if p not in seen:
            steps.append({"do": "remove", "path": p, "file": have[p]["file"],
                          "base": have[p]["version"]})
    return {"steps": steps, "same": same}


def manifest_paths(manifest, root):
    """The repository paths of a projection manifest `{path: {...}}` (hive
    paths): relative to the workspace root (OR-FJ-70), without any path
    outside it or with a `.git` segment (OR-FJ-72), sorted."""
    if isinstance(manifest, str):
        try:
            manifest = json.loads(manifest)
        except Exception:
            manifest = {}
    if not isinstance(manifest, dict):
        return []
    out = set()
    for p in manifest:
        rel = repo_path(p, root)
        if rel is not None and not git_segment(rel):
            out.add(rel)
    return sorted(out)


def unstaged(index_paths, paths):
    """The paths the index holds but the manifest no longer names."""
    keep = set(paths)
    return sorted(p for p in index_paths if p and p not in keep)


def parents_of(head, upstream, upstream_in_head):
    """The parents of an export commit: the old head, then the upstream while
    it is no ancestor of the head yet (a push after a pull fast-forwards)."""
    out = [head] if head else []
    if upstream and upstream != head and not upstream_in_head:
        out.append(upstream)
    return out


def nul_list(paths):
    return ("\x00".join(paths) + "\x00").encode("utf-8") if paths else b""


def v12(version):
    return str(version or "")[:12]


def jload(value, default):
    if isinstance(value, (dict, list)):
        return value
    try:
        out = json.loads(value or "")
    except Exception:
        return default
    return out if isinstance(out, type(default)) else default


# ================================================================ PLUMBING
class GitError(Exception):
    def __init__(self, code, message):
        Exception.__init__(self, message)
        self.code = code


def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def ago(ms):
    t = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(milliseconds=ms)
    return t.strftime(FMT)


def emit(msgs):
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def park(reason=""):
    if reason:
        sys.stderr.write("projection/git: %s\n" % reason)
    emit([])


def knob(name, default):
    v = P.get(name)
    if isinstance(v, bool) or v is None or v == "":
        return default
    if isinstance(default, int):
        try:
            return int(v)
        except Exception:
            return default
    return v


def run(cmd, stdin=b"", ok=(0,)):
    """One `git` call; its exit, stdout (bytes) and stderr (text, masked)."""
    try:
        p = subprocess.run(cmd, input=stdin, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                           env=GIT_ENV, timeout=knob("git_timeout_ms", 60000) / 1000.0,
                           shell=False)
    except subprocess.TimeoutExpired:
        raise GitError("git_timeout", "a git call ran longer than git_timeout_ms")
    except OSError as e:
        raise GitError("git_failed", "git did not start: %s" % e)
    err = tail(p.stderr.decode("utf-8", "replace"))
    if p.returncode not in ok:
        raise GitError("git_failed", err or "git exited %d" % p.returncode)
    return p.returncode, p.stdout, err


def out(cmd, **kw):
    return run(cmd, **kw)[1].decode("utf-8", "replace").strip()


def rev(repo, name):
    """The commit a ref names, '' if it names none."""
    code, so, _ = run(argv(repo, "rev-parse", "--verify", "--quiet", name + "^{commit}"),
                      ok=(0, 1))
    return so.decode("ascii", "replace").strip() if code == 0 else ""


def has_repo(repo):
    return os.path.isfile(os.path.join(gitdir_of(repo), "HEAD"))


def ensure_repo(repo):
    """The work tree and its bare repository under `git_dir` (no template:
    not even a sample hook is copied in)."""
    os.makedirs(repo, exist_ok=True)
    if not has_repo(repo):
        gd = gitdir_of(repo)
        os.makedirs(gd, exist_ok=True)
        run(["git", "init", "--quiet", "--bare", "--template=", "-b", "main", gd])


def read_blobs(repo, shas):
    """The bytes of every blob in `shas`, through one `cat-file --batch`."""
    if not shas:
        return {}
    _, so, _ = run(argv(repo, "cat-file", "--batch"),
                   stdin=("\n".join(shas) + "\n").encode("ascii"))
    got, i = {}, 0
    for sha in shas:
        nl = so.index(b"\n", i)
        head = so[i:nl].decode("ascii", "replace").split()
        if len(head) < 3 or head[1] != "blob":
            raise GitError("git_failed", "cat-file: no blob %s" % sha)
        size = int(head[2])
        got[sha] = so[nl + 1:nl + 1 + size]
        i = nl + 1 + size + 1
    return got


def store(ops, phase):
    """One bundle to `./store`; the store edge lifts `phase` into
    `context.cur_phase` and `reply_cell` into `cur_origin`."""
    return {"header": {"route": "git_store", "phase": phase, "reply_cell": ME},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def sel(table, columns, where, limit=ROW_LIMIT):
    return {"operation": "select", "table": table, "columns": columns, "where": where,
            "limit": limit}


def ins(table, row):
    return {"operation": "insert", "table": table, "row": row}


def upd(table, setv, where):
    return {"operation": "update", "table": table, "set": setv, "where": where}


def dele(table, where):
    return {"operation": "delete", "table": table, "where": where}


def legs(body):
    """The answer of a store message by tool_call id (curator/intake)."""
    res = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        res[str(m.get("id") or "")] = {"payload": payload, "error_code": ""}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = res.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": ""})
                leg["error_code"] = str(r.get("error_code") or "")
    elif len(res) == 1:
        next(iter(res.values()))["error_code"] = str(hop.get("error_code") or "")
    return res


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return p if isinstance(p, list) else []


# ================================================================ JOBS
def job_ops(job, first=False):
    row = {"op_id": job["id"], "cell": ME, "phase": "job", "body": json.dumps(job), "at": now()}
    if first:
        return [("j-stale", dele("pending", {"cell": ME, "at": {"lt": ago(JOB_TTL_MS)}})),
                ("j-put", ins("pending", row))]
    return [("j-put", upd("pending", {"body": row["body"], "at": row["at"]},
                          {"op_id": job["id"], "cell": ME, "phase": "job"}))]


def reply(job, payload):
    h = {"route": "answer", "op": job["op"], "op_id": job["op_id"], "caller": job["caller"],
         "ws": job["ws"]}
    body = {"ok": True, "op": job["op"], "op_id": job["op_id"], "messages": []}
    body.update(payload)
    return dict(echo_root(job, body), header=h)


def refuse(job, code, message, **extra):
    h = {"route": "answer", "op": job.get("op", ""), "op_id": job.get("op_id", ""),
         "caller": job.get("caller", ""), "ws": job.get("ws", "")}
    err = {"code": code, "message": tail(message)}
    err.update(extra)
    return echo_root(job, {"header": h, "ok": False, "op": job.get("op", ""),
                           "op_id": job.get("op_id", ""), "error": err, "messages": []})


def echo_root(job, body):
    """GH #980 (OR-LP-65): an answer of the root form names the `root` it
    exported or pushed, so a record of export and push binds to the folder of
    the task -- a subject alone also matches an export of another folder."""
    if job.get("root_form"):
        body["root"] = job.get("view_root") or "/"
    return body


def close(job, answer):
    """The job's own `pending` rows go, the answer leaves."""
    return [store([("j-drop", dele("pending", {"op_id": job["id"], "cell": ME}))],
                  "done|" + job["id"]), answer]


def finish(job, answer):
    """The end of a job. An export of the root form opened its view: the view
    is discarded first and `answer` leaves once the space confirmed it
    (`discarding`), so no open workspace outlives the call (GH #980)."""
    if not job.get("opened") or job.get("discarding"):
        return close(job, answer)
    job["discarding"] = True
    job["final"] = answer
    return call(job, False, "in_ws", "ws_discard", "", {}, CALLER)


def call(job, first, route, op, file, args, caller):
    """Park the job and ask another cell in ONE emission, the job row ahead
    of the question: `./store` answers in arrival order, so the answer -- in
    whatever shape it comes back -- always finds the job (ws `put`)."""
    n = int(job.get("n") or 0) + 1
    job["n"] = n
    job["await"] = "ans:%d" % n
    h = {"route": route, "op": op, "op_id": "git:%s.%d" % (job["id"], n), "caller": caller,
         "ws": job["ws"]}
    msg = {"header": h, "op": op, "args": args, "messages": []}
    if file:
        msg["file"] = file
    return [store(job_ops(job, first), "nop|" + job["id"]), msg]


def repo_of(job):
    return os.path.join(P.get("base_path") or "", job["ws"])


def use_env(job):
    """HOME is the repository under `git_dir`, which no program of `run` can
    write: git reads no one's configuration, not even a `.config/git/` a
    program left in the work tree (GH #980 M1)."""
    GIT_ENV.clear()
    GIT_ENV.update(git_env(gitdir_of(repo_of(job)), knob("git_author", DEFAULT_AUTHOR)))


# ================================================================ THE OPS
def do_push(job):
    repo = repo_of(job)
    a = job["args"]
    remotes = P.get("remotes")
    if job.get("root_form"):
        # GH #980: the root form is a model's tool -- a name the owner
        # configured, never a URL or a path the model typed.
        name = str(a.get("remote") or "")
        url = remotes[name] if (isinstance(remotes, dict) and isinstance(remotes.get(name), str)
                                and remotes.get(name)) else None
        if url is None:
            return refuse(job, "remote_unknown", "remote must be a name of `remotes`")
    else:
        url = resolve_remote(a.get("remote"), remotes)
    branch = str(a.get("branch") or "main")
    if url is None:
        return refuse(job, "remote_unknown", "remote must be a name of `remotes` or an absolute path")
    if has_userinfo(url):
        return refuse(job, "credentials_unsupported", CRED_MSG)
    if remote_inside_base(url, P.get("base_path")):
        return refuse(job, "remote_inside_base",
                      "a remote that is a local path must lie outside base_path")
    if not valid_ref(branch):
        return refuse(job, "bad_request", "branch is not a valid branch name")
    head = rev(repo, "HEAD") if has_repo(repo) else ""
    if not head:
        return refuse(job, "not_exported", "export the workspace (ws_export_git) before a push")
    code, so, err = run(argv_push(repo, url, branch, head), ok=(0, 1, 128))
    if code != 0:
        text = err + "\n" + so.decode("utf-8", "replace")
        if "rejected" in text or "non-fast-forward" in text or "fetch first" in text:
            return refuse(job, "push_rejected", text.strip())
        return refuse(job, "git_failed", text.strip())
    return reply(job, {"remote": mask(a.get("remote")), "branch": branch, "commit": head})


def do_fetch(job):
    """Import, first half: fetch, remember, read the tree; the entries of the
    job, or a refusal. Nothing is written into the hive before this passed."""
    repo = repo_of(job)
    a = job["args"]
    if job["op"] == "ws_pull":
        source, ref = a.get("remote"), str(a.get("branch") or "main")
    else:
        source, ref = a.get("source"), str(a.get("ref") or "HEAD")
    url = resolve_remote(source, P.get("remotes"))
    if url is None:
        raise GitError("remote_unknown", "source must be a name of `remotes` or an absolute path")
    if has_userinfo(url):
        raise GitError("credentials_unsupported", CRED_MSG)
    if not valid_ref(ref) and ref != "HEAD":
        raise GitError("bad_request", "ref is not a valid ref name")
    ensure_repo(repo)
    run(argv_fetch(repo, url, ref))
    commit = rev(repo, "FETCH_HEAD")
    if not commit:
        raise GitError("git_failed", "the fetch named no commit")
    _, raw, _ = run(argv(repo, "ls-tree", "-r", "-z", "-l", "--full-tree", commit))
    tree = parse_ls_tree(raw)
    if len(tree) > knob("import_max_files", 2000):
        raise GitError("too_many_files", "%d entries > import_max_files %d"
                       % (len(tree), knob("import_max_files", 2000)))
    # NOT the upstream yet (review I-1): an upstream set here outlived every
    # failure after the fetch (cat-file, ws_tree, a store error, a refused
    # write), the next export took it as a parent over a tree without the
    # foreign change and the push fast-forwarded that change away -- measured
    # with a real git, `a_failed_pull_never_moves_the_upstream`.
    run(argv(repo, "update-ref", INCOMING, commit))
    max_bytes = knob("import_max_bytes", 26214400)
    keep, skipped = [], []
    for e in tree:
        why = skip_reason(e, max_bytes)
        if why:
            # repository-relative here; the root is known after `ws_tree`
            skipped.append({"path": e["path"], "reason": why})
        else:
            keep.append(e)
    blobs = read_blobs(repo, sorted(set(e["sha"] for e in keep)))
    entries = [{"path": e["path"], "sha": e["sha"],
                "digest": hashlib.sha256(blobs[e["sha"]]).hexdigest()} for e in keep]
    return commit, entries, skipped


def do_export(job, prow):
    repo = repo_of(job)
    paths = manifest_paths((prow or {}).get("manifest"), job.get("root") or "/")
    ensure_repo(repo)
    if paths:
        # `-f`: a `.gitignore` of an imported repository must not keep a
        # file of the workspace out of its own export.
        run(argv(repo, "add", "-f", "--pathspec-from-file=-", "--pathspec-file-nul"),
            stdin=nul_list(paths))
    _, idx, _ = run(argv(repo, "ls-files", "-z", "--cached"))
    gone = unstaged([p for p in idx.decode("utf-8", "surrogateescape").split("\x00")], paths)
    if gone:
        run(argv(repo, "rm", "--cached", "--quiet", "--pathspec-from-file=-",
                 "--pathspec-file-nul"), stdin=nul_list(gone))
    tree = out(argv(repo, "write-tree"))
    head = rev(repo, "HEAD")
    upstream = rev(repo, UPSTREAM)
    inside = bool(upstream and head and run(
        argv(repo, "merge-base", "--is-ancestor", upstream, head), ok=(0, 1))[0] == 0)
    # L-8 of the coding proof (GH #980): the first export after a pull into a
    # fresh repository committed the pulled tree once more -- HEAD was empty,
    # so the check against HEAD never ran, and a merge commit over an
    # unchanged tree went to the remote. A tree that IS the upstream's, while
    # the upstream is no ancestor of HEAD (no HEAD at all, a HEAD behind it, or
    # beside it), moves HEAD onto the upstream and commits nothing; a HEAD
    # that already holds the upstream keeps the check against itself below.
    # A HEAD BESIDE the upstream (local exports nobody pushed) leaves HEAD's
    # line with that move: it is kept as `refs/meclaw/superseded/<sha>`
    # first, and the answer names it as `previous` -- nothing is ever deleted
    # (review m1, `an_export_beside_the_upstream_keeps_the_old_head`).
    if upstream and not inside and out(argv(repo, "rev-parse", upstream + "^{tree}")) == tree:
        if head and run(argv(repo, "merge-base", "--is-ancestor", head, upstream),
                        ok=(0, 1))[0] != 0:
            run(argv(repo, "update-ref", SUPERSEDED + head, head))
        run(argv(repo, "update-ref", "HEAD", upstream))
        ans = nothing(job, upstream, "the workspace is what the upstream already holds")
        if head:
            ans["previous"] = head
        return ans
    parents = parents_of(head, upstream, inside)
    if head and len(parents) == 1 and out(argv(repo, "rev-parse", head + "^{tree}")) == tree:
        return nothing(job, head, "the workspace is what the head already holds")
    note = str(job["args"].get("note") or "") or "meclaw export of workspace %s" % job["ws"]
    commit = out(argv_commit_tree(repo, tree, parents, note))
    run(argv(repo, "update-ref", "HEAD", commit))
    # GH #980 (WZ.3): the answer names the subject it committed under -- read
    # from git, never rebuilt: git joins the lines of the first paragraph
    # (`a\nb` is `a b`), a rebuilt first line was `a` (review m3).
    subject = out(argv(repo, "log", "-1", "--format=%s", commit))
    return reply(job, {"commit": commit, "files": len(paths), "subject": subject})


def nothing(job, commit, message):
    """`nothing_to_commit`, naming the commit HEAD now holds."""
    ans = refuse(job, "nothing_to_commit", message)
    ans["commit"] = commit
    return ans


def next_write(job):
    """The next step of an import, or the answer once none is left."""
    steps = job["steps"]
    i = int(job.get("i") or 0)
    if i >= len(steps):
        # Every write went through: now, and only now, the fetched commit is
        # what the workspace holds, and the next export may name it a parent.
        # A write the space refused keeps the upstream where it was, so a push
        # stays `push_rejected` until a pull that landed whole (review I-1).
        adopted = ""
        if not job.get("refused"):
            run(argv(repo_of(job), "update-ref", UPSTREAM, job["upstream"]))
            adopted = job["upstream"]
        t = job["tally"]
        return close(job, reply(job, {"created": t["created"], "modified": t["modified"],
                                      "removed": t["removed"], "skipped": job["skipped"],
                                      "upstream": adopted}))
    s = steps[i]
    job["i"] = i + 1
    if s["do"] == "remove":
        return call(job, False, "in_write", "remove", s["file"], {"base": s["base"]}, CALLER)
    data = read_blobs(repo_of(job), [s["sha"]])[s["sha"]]
    b = base64.b64encode(data).decode("ascii")
    if s["do"] == "create":
        return call(job, False, "in_write", "create", "", {"path": s["path"], "b64": b}, CALLER)
    return call(job, False, "in_write", "overwrite", s["file"], {"b64": b, "base": s["base"]},
                CALLER)


# ================================================================ LANES
lane = str(hop.get("route") or "")
phase = str(ctx.get("cur_phase") or "")

if lane == "in_proj":
    op = str(d.get("op") or hop.get("op") or "")
    args = d.get("args") if isinstance(d.get("args"), dict) else {}
    job = {"id": "gj-" + secrets.token_hex(8), "op": op, "op_id": str(hop.get("op_id") or ""),
           "caller": str(hop.get("caller") or ""), "ws": str(hop.get("ws") or args.get("ws") or ""),
           "args": args}
    if not job["op_id"]:
        emit([refuse(job, "bad_request", "op_id is required")])
    if op not in OPS:
        emit([refuse(job, "unknown_op", "no git op %r" % op)])
    if "root" in args and op in ("ws_export_git", "ws_push"):
        # GH #980: the root form (see the head of this script).
        if job["ws"]:
            emit([refuse(job, "bad_request", "name a workspace or a root, not both")])
        root = norm_root(args.get("root"))
        if root is None:
            emit([refuse(job, "bad_request", "root must be an absolute folder path")])
        job.update({"ws": view_of(root), "root_form": True, "view_root": root})
    if not NAME_RE.match(job["ws"]) or job["ws"] in (".", ".."):
        emit([refuse(job, "ws_unknown", "name the workspace in hop.ws")])
    if not str(P.get("base_path") or "").startswith("/"):
        emit([refuse(job, "no_base_path", "the projection has no base_path (owner override)")])
    if git_root(P.get("base_path"), P.get("git_dir")) is None:
        emit([refuse(job, "no_git_dir", "the projection has no git_dir outside base_path "
                                       "(owner override, granted to the git cell alone)")])
    use_env(job)
    try:
        if op == "ws_push":
            emit([do_push(job)])
        if op == "ws_export_git" and job.get("root_form"):
            emit(call(job, True, "in_ws", "ws_open", "",
                      {"name": job["ws"], "root": job["view_root"]}, CALLER))
        if op == "ws_export_git":
            emit(call(job, True, "in_proj", "ws_materialize", "", {}, ME))
        commit, entries, skipped = do_fetch(job)
    except GitError as e:
        emit([refuse(job, e.code, str(e))])
    job.update({"entries": entries, "skipped": skipped, "upstream": commit})
    emit(call(job, True, "in_ws", "ws_tree", "", {}, CALLER))

if lane == "in_answer":
    sub = str(hop.get("op_id") or d.get("op_id") or "")
    jid, _, n = sub[4:].rpartition(".") if sub.startswith("git:") else ("", "", "")
    if not jid or not n.isdigit():
        park("an answer without a git job id (%r) -- dropped" % sub)
    answer = {k: v for k, v in d.items() if k not in ("header", "messages")}
    emit([store([("a-put", ins("pending", {"op_id": jid, "cell": ME, "phase": "ans:" + n,
                                           "body": json.dumps(answer), "at": now()})),
                 ("j-echo", sel("pending", ["phase", "body"], {"op_id": jid, "cell": ME}))],
                "job|" + jid)])

if lane:
    park("unknown lane %r -- dropped" % lane)

# ================================================================ STORE ANSWERS
kind, _, key = phase.partition("|")
if not key:
    park("a message with neither a lane nor a store phase -- dropped")
lg = legs(d)
bad = ["%s=%s" % (k, v["error_code"]) for k, v in lg.items() if v["error_code"]]
if kind in ("done", "nop"):
    if bad:
        sys.stderr.write("projection/git: store legs failed in %s: %s\n" % (phase, ",".join(bad)))
    emit([])

job, answers = None, {}
for r in rows(lg, "j-echo"):
    ph = str(r.get("phase") or "")
    if ph == "job":
        job = jload(r.get("body"), {})
    elif ph.startswith("ans:"):
        answers[ph] = jload(r.get("body"), {})
if kind not in ("job", "proj"):
    park("store answer in unknown phase %r -- dropped" % phase)
if not job:
    park("job %s came back without its row (%s) -- dropped" % (key, ",".join(bad)))
use_env(job)
if bad:
    emit(finish(job, refuse(job, "store_error", "store legs failed: %s" % ",".join(bad))))

if kind == "proj":
    prows = rows(lg, "proj")
    if not prows:
        emit(finish(job, refuse(job, "not_materialized", "the projection holds no manifest")))
    try:
        emit(finish(job, do_export(job, prows[0])))
    except GitError as e:
        emit(finish(job, refuse(job, e.code, str(e))))

a = answers.get(job.get("await") or "")
if a is None:
    park("job %s: %s has not arrived -- dropped" % (key, job.get("await")))
drop = [("a-drop", dele("pending", {"op_id": job["id"], "cell": ME, "phase": job["await"]}))]

def with_drop(msgs):
    """The answer just read leaves `pending` in the job's next store bundle."""
    if msgs and msgs[0].get("header", {}).get("route") == "git_store":
        msgs[0]["messages"] = [{"origin": "assistant", "type": "tool_call", "id": cid,
                                "text": json.dumps(args)} for cid, args in drop] + msgs[0]["messages"]
    return msgs


if job["op"] == "ws_export_git" and job.get("discarding"):
    # The view of a root-form export is discarded (GH #980): the answer kept
    # in the job leaves now. A refused discard does not change it -- the
    # export happened -- and is said on stderr.
    if not a.get("ok"):
        sys.stderr.write("projection/git: the view %s was not discarded: %s\n"
                         % (job["ws"], json.dumps(a.get("error"))))
    emit(close(job, job["final"]))

if job["op"] == "ws_export_git" and job.get("root_form") and not job.get("opened"):
    # `ws_open` of the view answered. A refusal (`ws_exists`: a workspace of
    # that name is open) ends the export before anything is laid out.
    # The refusal names the view (review m2): the owner learns WHICH
    # workspace to discard.
    if not a.get("ok"):
        err = a.get("error") if isinstance(a.get("error"), dict) else {}
        emit(close(job, refuse(job, str(err.get("code") or "ws_unknown"),
                               str(err.get("message") or "the view could not be opened"),
                               view=job["ws"])))
    job["opened"] = True
    emit(with_drop(call(job, False, "in_proj", "ws_materialize", "", {}, ME)))

if job["op"] == "ws_export_git" and not job.get("mat_done"):
    # `./mat` answered. A refusal, or a directory holding changes nobody
    # adopted (`dirty`, J answers it inside an ok), or files it could not lay
    # out stop the export: a commit of that directory would not be the
    # workspace.
    err = a.get("error") if isinstance(a.get("error"), dict) else {}
    if not a.get("ok"):
        code = str(err.get("code") or "materialize_failed")
        code = "dirty_projection" if code in ("dirty", "dirty_projection") else code
        emit(with_drop(finish(job, refuse(job, code,
                                          str(err.get("message") or "materialize failed")))))
    if a.get("dirty"):
        emit(with_drop(finish(job, refuse(job, "dirty_projection",
                                          "the projection holds changes nobody adopted"))))
    if a.get("failed"):
        emit(with_drop(finish(job, refuse(job, "materialize_failed",
                                          "a file could not be laid out"))))
    # The manifest keys are hive paths; the commit is root-relative
    # (OR-FJ-70), and only `ws_tree` names the root.
    job["mat_done"] = True
    emit(with_drop(call(job, False, "in_ws", "ws_tree", "", {}, CALLER)))

if job["op"] == "ws_export_git":
    if not a.get("ok"):
        err = a.get("error") if isinstance(a.get("error"), dict) else {}
        emit(with_drop(finish(job, refuse(job, str(err.get("code") or "ws_tree_failed"),
                                          str(err.get("message") or "ws_tree failed")))))
    job["root"] = str(a.get("root") or "/")
    emit([store(drop + job_ops(job) + [
        ("j-echo", sel("pending", ["phase", "body"],
                       {"op_id": job["id"], "cell": ME, "phase": "job"}, 1)),
        ("proj", sel("proj", ["ws", "dir", "manifest"], {"ws": job["ws"]}, 1))],
        "proj|" + job["id"])])

# ws_import_git / ws_pull
if "steps" not in job:
    if not a.get("ok"):
        err = a.get("error") if isinstance(a.get("error"), dict) else {}
        emit(close(job, refuse(job, str(err.get("code") or "ws_tree_failed"),
                               str(err.get("message") or "ws_tree failed"))))
    # The repository maps onto the workspace root (OR-FJ-70): skipped
    # entries become hive paths now, and none of them is removed.
    root = str(a.get("root") or "/")
    for sk in job["skipped"]:
        sk["path"] = hive_path(sk["path"], root) if repo_path(
            hive_path(sk["path"], root), root) is not None else "/" + sk["path"]
    plan = import_plan(job.pop("entries"), a.get("files") or [], root,
                       [sk["path"] for sk in job["skipped"]])
    job["steps"] = plan["steps"]
    job["tally"] = {"created": 0, "modified": 0, "removed": 0}
else:
    s = job["steps"][int(job["i"]) - 1]
    if a.get("ok"):
        job["tally"][{"create": "created", "overwrite": "modified", "remove": "removed"}[s["do"]]] += 1
    else:
        err = a.get("error") if isinstance(a.get("error"), dict) else {}
        job["skipped"].append({"path": s["path"], "reason": str(err.get("code") or "refused")})
        job["refused"] = True
try:
    msgs = next_write(job)
except GitError as e:
    msgs = close(job, refuse(job, e.code, str(e)))
emit(with_drop(msgs))
